package com.bananalab.lite;
import org.json.*;import java.util.*;
/** Full-gradient learning of source-derived examples and our own dialogue examples. No generated labels. */
final class ReadingWeights{
 interface Governor{void check()throws Exception;}
 static final class Batch{
  final List<TransformerTraining.Sequence> train=new ArrayList<>(),eval=new ArrayList<>();
  String id="",sha="",source="",origin="authored";int ordinal,offset,nextOrdinal,nextOffset,facts,rawTrainTokens,rawEvalTokens;boolean sourceBatch;JSONObject exercise;
 }
 static JSONArray dialogue(String split)throws Exception{String[][] rows=split.equals("train")?new String[][]{{"no me entendiste","decime que parte entendi mal ."},{"que podes hacer","puedo conversar y crear escenas ."},{"sabes todo","no . puedo equivocarme ."}}:new String[][]{{"me entendiste mal","decime que parte entendi mal ."},{"en que me ayudas","puedo conversar y crear escenas ."},{"entendes cualquier cosa","no . puedo equivocarme ."}};JSONArray out=new JSONArray();for(String[] r:rows)out.put(new JSONObject().put("question",r[0]).put("answer",r[1]));return out;}
 static List<TransformerTraining.Sequence> sequences(BananaTransformer m,JSONArray rows)throws Exception{List<TransformerTraining.Sequence> out=new ArrayList<>();for(int i=0;i<rows.length();i++)out.add(TransformerTraining.sequence(m,rows.getJSONObject(i)));return out;}
 static boolean fits(BananaTransformer m,String q,String a){return m.encode(q,8192).size()<=48&&m.encode(a,8192).size()<=24&&!a.trim().isEmpty();}
 static TransformerTraining.Sequence language(List<Integer> tokens,int start,int size){int[] input=new int[size+2],labels=new int[size+2];Arrays.fill(labels,-1);input[0]=2;input[1]=4;for(int i=0;i<size;i++){input[i+2]=tokens.get(start+i);labels[i+1]=tokens.get(start+i);}labels[labels.length-1]=5;return new TransformerTraining.Sequence(input,labels);}
 static Batch source(BananaTransformer m,NotebookDisk.Doc doc,String text,int ordinal,int offset)throws Exception{return source(m,doc,text,ordinal,offset,72);}
 static Batch source(BananaTransformer m,NotebookDisk.Doc doc,String text,int ordinal,int offset,int widthLimit)throws Exception{Batch b=new Batch();b.id=doc.id;b.sha=doc.sha;b.source=doc.source;b.origin=doc.origin;b.ordinal=ordinal;b.offset=offset;b.sourceBatch=true;
  if(offset==0){JSONArray rows=new JSONArray().put(doc.row(text));for(ReadingKnowledge.Definition d:ReadingKnowledge.definitions(rows)){String sentence=d.sentence;java.util.regex.Matcher match=java.util.regex.Pattern.compile(" (?:es|son|significa|se define como|consiste en) ",java.util.regex.Pattern.CASE_INSENSITIVE|java.util.regex.Pattern.UNICODE_CASE).matcher(sentence);if(!match.find())continue;String answer=sentence.substring(match.end()).trim(),train="que es "+d.term,eval="que significa "+d.term;if(fits(m,train,answer)&&fits(m,eval,answer)){b.train.add(TransformerTraining.sequence(m,new JSONObject().put("question",train).put("answer",answer)));b.eval.add(TransformerTraining.sequence(m,new JSONObject().put("question",eval).put("answer",answer)));if(++b.facts>=2)break;}}}
  List<Integer> tokens=m.encode(text,16384);if(offset<0||offset>tokens.size())throw new IllegalArgumentException("Cursor de lectura inválido");int width=Math.min(widthLimit,(tokens.size()-offset)/2);if(width>=6){b.train.add(language(tokens,offset,width));b.eval.add(language(tokens,offset+width,width));b.rawTrainTokens=width;b.rawEvalTokens=width;b.nextOffset=offset+2*width;b.nextOrdinal=ordinal;if(tokens.size()-b.nextOffset<12){b.nextOrdinal=ordinal+1;b.nextOffset=0;}}else{b.nextOrdinal=ordinal+1;b.nextOffset=0;}return b;
 }
 static Batch authored(BananaTransformer m)throws Exception{Batch b=new Batch();b.train.addAll(sequences(m,dialogue("train")));b.eval.addAll(sequences(m,dialogue("eval")));return b;}
 static double evaluate(BananaTransformer m,List<TransformerTraining.Sequence> rows)throws Exception{return evaluate(m,rows,null);}
 static double evaluate(BananaTransformer m,List<TransformerTraining.Sequence> rows,Governor governor)throws Exception{double total=0;for(TransformerTraining.Sequence s:rows){BananaTransformer.Session session=m.session();double nll=0;int n=0;for(int i=0;i<s.input.length;i++){if(governor!=null)governor.check();float[] p=HeadTrainer.probabilities(session.step(s.input[i]));if(s.labels[i]>=0){nll-=Math.log(Math.max(1e-12,p[s.labels[i]]));n++;}}total+=nll/Math.max(1,n);}return total/Math.max(1,rows.size());}
 static void restore(BananaTransformer m,float[][] snapshot){List<float[]> params=TransformerTraining.parameters(m);for(int i=0;i<snapshot.length;i++)System.arraycopy(snapshot[i],0,params.get(i),0,snapshot[i].length);}
 static JSONObject fit(BananaTransformer m,BananaTransformer base,Batch batch,Governor governor)throws Exception{return fit(m,base,batch,governor,false);}
 static JSONObject fit(BananaTransformer m,BananaTransformer base,Batch batch,Governor governor,boolean micro)throws Exception{if(batch.train.isEmpty()||batch.eval.isEmpty())throw new IllegalArgumentException("Sin ejemplos suficientes de la fuente");governor.check();JSONArray anchorRows=NeuralTraining.defaultRows("anchor");List<TransformerTraining.Sequence> replay=sequences(m,anchorRows),dialogueTrain=sequences(m,dialogue("train")),dialogueEval=sequences(m,dialogue("eval"));float[][] snapshot=TransformerTraining.snapshot(m);float[][] previous=HeadTrainer.distributions(NeuralTraining.tokens(m,anchorRows),m.head,m.headBias),stable=HeadTrainer.distributions(NeuralTraining.tokens(base,anchorRows),base.head,base.headBias);double before=evaluate(m,batch.eval,governor),dialogueBefore=evaluate(m,dialogueEval,governor);int epochs=micro?1:2;if(micro){dialogueTrain=new ArrayList<>(dialogueTrain.subList(0,1));replay=new ArrayList<>(replay.subList(0,1));}
  for(int epoch=0;epoch<epochs;epoch++){for(TransformerTraining.Sequence s:batch.train){governor.check();TransformerTraining.Tape tape=new TransformerTraining.Tape();TransformerTraining.Tensor logits=TransformerTraining.forward(m,tape,s.input);TransformerTraining.loss(logits,s.labels,true);tape.backward();tape.update(.001f);TransformerTraining.project(m,snapshot,.05);}if(batch.sourceBatch)for(TransformerTraining.Sequence s:dialogueTrain){governor.check();TransformerTraining.step(m,s);TransformerTraining.project(m,snapshot,.05);}for(TransformerTraining.Sequence s:replay){governor.check();TransformerTraining.step(m,s);TransformerTraining.project(m,snapshot,.05);}}
  governor.check();double after=evaluate(m,batch.eval,governor),dialogueAfter=evaluate(m,dialogueEval,governor),kl=HeadTrainer.divergence(NeuralTraining.tokens(m,anchorRows),previous,m.head,m.headBias),stableKL=HeadTrainer.divergence(NeuralTraining.tokens(m,anchorRows),stable,m.head,m.headBias),delta=TransformerTraining.distance(m,snapshot);boolean accepted=!Double.isNaN(after)&&!Double.isInfinite(after)&&after<before-1e-5&&dialogueAfter<=dialogueBefore+.01&&kl<=.003&&stableKL<=.02&&delta>0;
  return new JSONObject().put("kind","chat").put("method","Full Transformer SGD from reading and authored dialogue").put("readingWeights",true).put("fullTransformer",true).put("accepted",accepted).put("before",before).put("after",after).put("dialogueBefore",dialogueBefore).put("dialogueAfter",dialogueAfter).put("anchorKL",kl).put("originalAnchorKL",stableKL).put("weightDeltaL2",delta).put("epochs",epochs).put("microBatch",micro).put("trainSequences",batch.train.size()).put("evalSequences",batch.eval.size()).put("definitionPairs",batch.facts).put("rawTrainTokens",batch.rawTrainTokens).put("rawEvalTokens",batch.rawEvalTokens).put("sourceId",batch.id).put("sourceSha256",batch.sha).put("source",batch.source).put("origin",batch.origin).put("ordinal",batch.ordinal).put("tokenOffset",batch.offset).put("nextOrdinal",batch.nextOrdinal).put("nextTokenOffset",batch.nextOffset).put("metric","held-out prompt/same-fact NLL and disjoint continuation NLL; not an external benchmark");
 }
}
